const input = $input.first();

const ALLOWED_FACILITY_IDS = Object.freeze([1]);
const MAX_BODY_BYTES = 4096;
const EVENT_TYPES = Object.freeze([
  'credential.created',
  'credential.verification_changed',
  'credential.expiry_due',
  'credential.lifecycle_changed',
  'employee.lifecycle_changed',
  'employee.invitation_changed',
  'schedule.lifecycle_changed',
  'schedule_request.lifecycle_changed',
]);
const EXPIRY_THRESHOLDS = Object.freeze([90, 60, 30, 15, 7, 1, 0]);
const CREDENTIAL_LIFECYCLE_CHANGES = Object.freeze(['updated', 'deleted']);
const EMPLOYEE_LIFECYCLE_CHANGES = Object.freeze([
  'created', 'updated', 'activated', 'deactivated',
]);
const EMPLOYEE_INVITATION_CHANGES = Object.freeze([
  'created', 'revoked', 'accepted',
]);
const SCHEDULE_LIFECYCLE_CHANGES = Object.freeze([
  'created', 'updated', 'published', 'reopened', 'cancelled',
]);
const SCHEDULE_REQUEST_LIFECYCLE_CHANGES = Object.freeze([
  'submitted', 'withdrawn', 'approved', 'rejected', 'approval_revoked',
]);
const REQUIRED_HEADERS = Object.freeze([
  'content-type',
  'idempotency-key',
  'x-health-credential-event-id',
  'x-health-credential-event-type',
  'x-health-credential-timestamp',
  'x-health-credential-signature',
]);

const reject = (statusCode, safeReason) => [{
  json: { precheckOk: false, statusCode, safeReason },
}];
const exactKeys = (value, expected) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  return actual.length === wanted.length
    && actual.every((key, index) => key === wanted[index]);
};
const exactChange = (data, allowed) => (
  exactKeys(data, ['change'])
  && typeof data.change === 'string'
  && allowed.includes(data.change)
);

const rawHeaders = input.json?.headers;
if (!rawHeaders || typeof rawHeaders !== 'object' || Array.isArray(rawHeaders)) {
  return reject(400, 'invalid_headers');
}
const headers = Object.create(null);
for (const requiredName of REQUIRED_HEADERS) {
  const matches = Object.entries(rawHeaders).filter(
    ([name]) => name.toLowerCase() === requiredName,
  );
  if (matches.length !== 1) return reject(400, 'invalid_headers');
  const value = matches[0][1];
  if (Array.isArray(value) || typeof value !== 'string' || /[,\r\n]/.test(value)) {
    return reject(400, 'invalid_headers');
  }
  headers[requiredName] = value;
}

if (!/^application\/json(?:\s*;\s*charset=utf-8)?$/i.test(headers['content-type'])) {
  return reject(415, 'unsupported_content_type');
}
const timestamp = headers['x-health-credential-timestamp'];
const signature = headers['x-health-credential-signature'];
if (!/^\d{10}$/.test(timestamp) || !/^sha256=[a-f0-9]{64}$/.test(signature)) {
  return reject(401, 'invalid_signature');
}

if (!input.binary?.data) return reject(400, 'missing_raw_body');
let rawBody;
try {
  rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch {
  return reject(400, 'missing_raw_body');
}
if (!Buffer.isBuffer(rawBody)
  || rawBody.length === 0
  || rawBody.length > MAX_BODY_BYTES) {
  return reject(400, 'invalid_body_size');
}
const rawText = rawBody.toString('utf8');
if (!Buffer.from(rawText, 'utf8').equals(rawBody)) {
  return reject(400, 'invalid_utf8');
}

let envelope;
try {
  envelope = JSON.parse(rawText);
} catch {
  return reject(400, 'invalid_json');
}
if (!exactKeys(envelope, ['id', 'type', 'occurredAt', 'facilityId', 'data'])) {
  return reject(400, 'invalid_payload');
}
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(envelope.id)) {
  return reject(400, 'invalid_payload');
}
if (headers['x-health-credential-event-id'] !== envelope.id
  || headers['idempotency-key'] !== envelope.id) {
  return reject(400, 'invalid_payload');
}
if (!EVENT_TYPES.includes(envelope.type)
  || headers['x-health-credential-event-type'] !== envelope.type) {
  return reject(400, 'invalid_payload');
}
if (typeof envelope.occurredAt !== 'string') return reject(400, 'invalid_payload');
let canonicalOccurredAt;
try {
  canonicalOccurredAt = new Date(envelope.occurredAt).toISOString();
} catch {
  return reject(400, 'invalid_payload');
}
if (canonicalOccurredAt !== envelope.occurredAt
  || !Number.isSafeInteger(envelope.facilityId)
  || !ALLOWED_FACILITY_IDS.includes(envelope.facilityId)) {
  return reject(403, 'facility_not_allowed');
}

const data = envelope.data;
let dataValid = false;
if (envelope.type === 'credential.created') {
  dataValid = exactKeys(data, []);
} else if (envelope.type === 'credential.verification_changed') {
  dataValid = exactKeys(data, ['isVerified']) && typeof data.isVerified === 'boolean';
} else if (envelope.type === 'credential.expiry_due') {
  dataValid = exactKeys(data, ['thresholdDays'])
    && EXPIRY_THRESHOLDS.includes(data.thresholdDays);
} else if (envelope.type === 'credential.lifecycle_changed') {
  dataValid = exactChange(data, CREDENTIAL_LIFECYCLE_CHANGES);
} else if (envelope.type === 'employee.lifecycle_changed') {
  dataValid = exactChange(data, EMPLOYEE_LIFECYCLE_CHANGES);
} else if (envelope.type === 'employee.invitation_changed') {
  dataValid = exactChange(data, EMPLOYEE_INVITATION_CHANGES);
} else if (envelope.type === 'schedule.lifecycle_changed') {
  dataValid = exactChange(data, SCHEDULE_LIFECYCLE_CHANGES);
} else if (envelope.type === 'schedule_request.lifecycle_changed') {
  dataValid = exactChange(data, SCHEDULE_REQUEST_LIFECYCLE_CHANGES);
}
if (!dataValid) return reject(400, 'invalid_payload');

return [{
  json: {
    precheckOk: true,
    timestamp,
    signature,
    rawBodyBase64: rawBody.toString('base64'),
  },
}];

const result = $input.first().json;
const receiptStatus = String(result.receipt_status ?? '');
const eventId = typeof result.event_id === 'string' ? result.event_id : null;
let statusCode = 500;
let responseBody = { accepted: false, code: 'receiver_error' };

if (receiptStatus === 'inserted' && eventId) {
  statusCode = 202;
  responseBody = { accepted: true, duplicate: false, eventId };
} else if (receiptStatus === 'duplicate' && eventId) {
  statusCode = 200;
  responseBody = { accepted: true, duplicate: true, eventId };
} else if (receiptStatus === 'conflict') {
  statusCode = 409;
  responseBody = { accepted: false, code: 'idempotency_conflict' };
} else if (receiptStatus === 'invalid_signature') {
  statusCode = 401;
  responseBody = { accepted: false, code: 'invalid_signature' };
} else if (receiptStatus === 'expired_signature') {
  statusCode = 401;
  responseBody = { accepted: false, code: 'expired_signature' };
} else if (receiptStatus === 'invalid_payload') {
  statusCode = 400;
  responseBody = { accepted: false, code: 'invalid_payload' };
} else if (receiptStatus === 'facility_not_allowed') {
  statusCode = 403;
  responseBody = { accepted: false, code: 'facility_not_allowed' };
} else if (receiptStatus === 'receiver_not_configured') {
  statusCode = 503;
  responseBody = { accepted: false, code: 'receiver_not_configured' };
}

return [{ json: { statusCode, responseBody } }];
